import os
import requests
from typing import Dict, Any, List

class AzureTranslatorClient:
    def __init__(self, api_key: str, region: str, endpoint: str = "https://api.cognitive.microsofttranslator.com"):
        self.api_key = api_key
        self.region = region
        self.endpoint = endpoint
        self.headers = {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Ocp-Apim-Subscription-Region': self.region,
            'Content-type': 'application/json'
        }
        self.params = {
            'api-version': '3.0'
        }

    def translate(self, text_elements: List[Dict[str, str]], source_language: str, target_language: str, text_type: str = "plain") -> List[Dict[str, Any]]:
        params = self.params.copy()
        params['from'] = source_language
        params['to'] = target_language
        if text_type == "html":
            params['textType'] = "html"

        response = requests.post(f'{self.endpoint}/translate',
            headers=self.headers,
            params=params,
            json=text_elements,
            timeout=30)
        response.raise_for_status()
        return response.json()

def get_azure_translator_client() -> AzureTranslatorClient:
    api_key = os.environ.get("AZURE_TRANSLATOR_API_KEY")
    region = os.environ.get("AZURE_TRANSLATOR_REGION")
    if not api_key or not region:
        raise ValueError("AZURE_TRANSLATOR_API_KEY and AZURE_TRANSLATOR_REGION environment variables must be set.")
    return AzureTranslatorClient(api_key=api_key, region=region)

from typing import List, Dict, Any
from translation_client import get_azure_translator_client
from translation_models import BatchTranslationRequest, BatchTranslationResponse

def batch_translate(request: BatchTranslationRequest) -> BatchTranslationResponse:
    client = get_azure_translator_client()

    text_elements = [{'Text': text} for text in request.texts]

    azure_response = client.translate(
        text_elements=text_elements,
        source_language=request.source_language,
        target_language=request.target_language
    )

    translated_texts = []
    for item in azure_response:
        if 'translations' in item and item['translations']:
            translated_texts.append(item['translations'][0]['text'])
        else:
            translated_texts.append("") # Handle cases where no translation is returned for an item

    return BatchTranslationResponse(
        translations=translated_texts,
        source_language=request.source_language,
        target_language=request.target_language
    )

from typing import Dict, Any
from translation_client import get_azure_translator_client
from translation_models import DictionaryTranslationRequest, DictionaryTranslationResponse

def translate_dictionary_values(request: DictionaryTranslationRequest) -> DictionaryTranslationResponse:
    client = get_azure_translator_client()

    original_keys = list(request.dictionary.keys())
    original_values = [request.dictionary[key] for key in original_keys]

    text_elements = [{'Text': value} for value in original_values]

    azure_response = client.translate(
        text_elements=text_elements,
        source_language=request.source_language,
        target_language=request.target_language
    )

    translated_dictionary = {}
    if azure_response:
        for i, key in enumerate(original_keys):
            translated_value = ""
            if 'translations' in azure_response[i] and azure_response[i]['translations']:
                translated_value = azure_response[i]['translations'][0]['text']
            translated_dictionary[key] = translated_value

    return DictionaryTranslationResponse(
        translated_dictionary=translated_dictionary,
        source_language=request.source_language,
        target_language=request.target_language
    )
